func  (this *bitvavo) AmountToPrecision(symbol interface{}, amount interface{}) interface{}  {
    // https://docs.bitfinex.com/docs/introduction#amount-precision
    // The amount field allows up to 8 decimals.
    // Anything exceeding this will be rounded to the 8th decimal.
    return this.DecimalToPrecision(amount, ccxt.TRUNCATE, ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Markets, symbol), "precision"), "amount"), ccxt.DECIMAL_PLACES)
}
func  (this *bitvavo) PriceToPrecision(symbol interface{}, price interface{}) interface{}  {
    price = this.DecimalToPrecision(price, ccxt.ROUND, ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Markets, symbol), "precision"), "price"), this.PrecisionMode)
    // https://docs.bitfinex.com/docs/introduction#price-precision
    // The precision level of all trading prices is based on significant figures.
    // All pairs on Bitfinex use up to 5 significant digits and up to 8 decimals (e.g. 1.2345, 123.45, 1234.5, 0.00012345).
    // Prices submit with a precision larger than 5 will be cut by the API.
    return this.DecimalToPrecision(price, ccxt.TRUNCATE, 8, ccxt.DECIMAL_PLACES)
}
