func  (this *bitvavo) Sign(path interface{}, optionalArgs ...interface{}) interface{}  {
    api := ccxt.GetArg(optionalArgs, 0, "public")
    _ = api
    method := ccxt.GetArg(optionalArgs, 1, "GET")
    _ = method
    params := ccxt.GetArg(optionalArgs, 2, map[string]interface{} {})
    _ = params
    headers := ccxt.GetArg(optionalArgs, 3, nil)
    _ = headers
    body := ccxt.GetArg(optionalArgs, 4, nil)
    _ = body
    var query interface{} = this.Omit(params, this.ExtractParams(path))
    var url interface{} = ccxt.Add(ccxt.Add(ccxt.Add("/", this.Version), "/"), this.ImplodeParams(path, params))
    var getOrDelete interface{} = ccxt.IsTrue((ccxt.IsEqual(method, "GET"))) || ccxt.IsTrue((ccxt.IsEqual(method, "DELETE")))
    if ccxt.IsTrue(getOrDelete) {
        if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
            url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
        }
    }
    if ccxt.IsTrue(ccxt.IsEqual(api, "private")) {
        this.CheckRequiredCredentials()
        var payload interface{} = ""
        if !ccxt.IsTrue(getOrDelete) {
            if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
                body = this.Json(query)
                payload = body
            }
        }
        var timestamp interface{} = ccxt.ToString(this.Milliseconds())
        var auth interface{} = ccxt.Add(ccxt.Add(ccxt.Add(timestamp, method), url), payload)
        var signature interface{} = this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha256)
        var accessWindow interface{} = this.SafeString(this.Options, "BITVAVO-ACCESS-WINDOW", "10000")
        headers = map[string]interface{} {
            "BITVAVO-ACCESS-KEY": this.ApiKey,
            "BITVAVO-ACCESS-SIGNATURE": signature,
            "BITVAVO-ACCESS-TIMESTAMP": timestamp,
            "BITVAVO-ACCESS-WINDOW": accessWindow,
        }
        if !ccxt.IsTrue(getOrDelete) {
            ccxt.AddElementToObject(headers, "Content-Type", "application/json")
        }
    }
    url = ccxt.Add(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), api), url)
    return map[string]interface{} {
        "url": url,
        "method": method,
        "body": body,
        "headers": headers,
    }
}
func  (this *bitvavo) HandleErrors(httpCode interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
        return nil  // fallback to default error handler
    }
    //
    //     {"errorCode":308,"error":"The signature length is invalid (HMAC-SHA256 should return a 64 length hexadecimal string)."}
    //     {"errorCode":203,"error":"symbol parameter is required."}
    //     {"errorCode":205,"error":"symbol parameter is invalid."}
    //
    var errorCode interface{} = this.SafeString(response, "errorCode")
    var err interface{} = this.SafeString(response, "error")
    if ccxt.IsTrue(!ccxt.IsEqual(errorCode, nil)) {
        var feedback interface{} = ccxt.Add(ccxt.Add(this.Id, " "), body)
        this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), err, feedback)
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
        panic(ccxt.ExchangeError(feedback))
    }
    return nil
}
func  (this *bitvavo) CalculateRateLimiterCost(api interface{}, method interface{}, path interface{}, params interface{}, optionalArgs ...interface{}) interface{}  {
    config := ccxt.GetArg(optionalArgs, 0, map[string]interface{} {})
    _ = config
    if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(config, "noMarket"))) && !ccxt.IsTrue((ccxt.InOp(params, "market")))) {
        return ccxt.GetValue(config, "noMarket")
    }
    return this.SafeValue(config, "cost", 1)
}


func (this *bitvavo) Init(userConfig map[string]interface{}) {
    this.Exchange = ccxt.Exchange{}
    this.Exchange.DerivedExchange = this
    this.Exchange.InitParent(userConfig, this.Describe().(map[string]interface{}), this)
}
